"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0813-01-01:1":{"b": ["Ο χάνος Κρούμ κατέλαβε την Αδριανούπολη", "ab7bbb89"], "d": ["Ο Βούλγαρος χάνος Κρούμ το 813 κατέλαβε την Αδριανούπολη και ο στρατός του ήρθε μπροστά στην Κωνσταντινούπολη.", "fa54d545"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0827-04-02:0":{"b": ["Ο στόλος Αγλαβιδών-Ευφημίου κατέκτησε τη Μάζαρα (Mazara del Vallo): άρχισε η κατάκτηση της Σικελίας", "a2676b9a"], "d": ["Όταν ο Βυζαντινός ναυτικός διοικητής Ευφήμιος εξεγέρθηκε κατά του διοικητή Κωνσταντίνου Σούδα και ζήτησε βοήθεια από τον Αγλαβίδη εμίρη Ζιγιαντουλλάχ, ήρθε μουσουλμανικός στόλος 10.000 ανδρών με πάνω από εβδομήντα πλοία υπό τον Ασάντ μπ. Φουράτ, ενώθηκε με τον Ευφήμιο και κατέκτησε τη Μάζαρα το 212 (827). Η κατάκτηση του νησιού θα διαρκέσει 75 χρόνια και θα ολοκληρωθεί το 902.", "cc8ea594"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0831-01-01:0":{"b": ["Επί Μαλαμίρ η Φιλιππούπολη προσαρτήθηκε στο βουλγαρικό κράτος", "f6c49ed3"], "d": ["Ο χάνος Μαλαμίρ (831-836) πρόσθεσε τη Φιλιππούπολη (Philippopolis) στα εδάφη του· στη συνέχεια ο χάνος Πρεσιάν κατέλαβε το μεγαλύτερο μέρος της Μακεδονίας.", "f8bd8891"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0831-02-18:0":{"b": ["Το Παλέρμο παραδόθηκε στους Αγλαβίδες μουσουλμάνους", "6adfd1ac"], "d": ["Μετά την πτώση της Μάζαρα, οι μουσουλμανικές δυνάμεις πολιόρκησαν το Παλέρμο· η πόλη παραδόθηκε το 216 (831). Το 840 θα καταλαμβάνονταν και το Platani, το Caltabellotta και το Corleone.", "8693fb4d"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0831-09-12:0":{"b": ["Το Παλέρμο παραδόθηκε στους μουσουλμάνους.", "4a74d5bb"], "d": ["Το Παλέρμο παραδόθηκε στους μουσουλμάνους.", "4a74d5bb"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0843-01-01:0":{"b": ["Η Μεσσήνη κατακτήθηκε· το Στενό της Μεσσήνης μεταξύ Σικελίας-Ιταλίας περιήλθε στον έλεγχο των μουσουλμάνων", "3c8d221c"], "d": ["Αφού το 840 καταλήφθηκαν το Platani, το Caltabellotta, το Corleone και το 842 ολόκληρη η περιοχή της Μάζαρα, την επόμενη χρονιά (843) κατακτήθηκε η Μεσσήνη στα βορειοανατολικά του νησιού και τέθηκε υπό έλεγχο το στρατηγικό στενό.", "87fda636"]},
